#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>

// Định nghĩa chân theo sơ đồ phần cứng đã kết nối
#define DHTPIN 2          // Chân PD2 -> DHT11 Data
#define DHTTYPE DHT11
#define FLAME_PIN 3       // Chân PD3 -> Cảm biến Lửa (Nút nhấn)
#define RELAY_PUMP 4      // Chân PD4 -> Relay Bơm/Van nước
#define BUZZER 5          // Chân PD5 -> Còi báo động
#define FAN_PIN 6         // Chân PD6 -> Quạt thông gió

DHT dht(DHTPIN, DHTTYPE);
LiquidCrystal_I2C lcd(0x27, 16, 2); // Địa chỉ I2C mặc định của PCF8574

// Các biến lưu thời gian để chạy đa nhiệm (Non-blocking)
unsigned long prevSensorMillis = 0;
unsigned long prevBuzzerMillis = 0;
const long sensorInterval = 1000;   // Đọc cảm biến mỗi 1 giây
const long buzzerInterval = 200;    // Nhịp còi báo động 200ms

bool buzzerState = LOW;

void setup() {
    // Cấu hình các chân IO
    pinMode(FLAME_PIN, INPUT_PULLUP); // Trạng thái bình thường là HIGH, có lửa là LOW
    pinMode(RELAY_PUMP, OUTPUT);
    pinMode(BUZZER, OUTPUT);
    pinMode(FAN_PIN, OUTPUT);

    // Tắt toàn bộ thiết bị công suất lúc khởi động
    digitalWrite(RELAY_PUMP, LOW);
    digitalWrite(BUZZER, LOW);
    digitalWrite(FAN_PIN, LOW);

    // Khởi tạo các module ngoại vi
    lcd.init();
    lcd.backlight();
    dht.begin();

    // Hiển thị màn hình chào mừng lúc khởi động
    lcd.setCursor(0, 0);
    lcd.print("  FIRE PUMP SYSTEM ");
    lcd.setCursor(0, 1);
    lcd.print("   INITIALIZING..  ");
    delay(2000); 
    lcd.clear();
}

void loop() {
    unsigned long currentMillis = millis();

    // Khai báo biến static để giữ giá trị giữa các chu kỳ loop
    static float t = 0;
    static float h = 0;
    static bool isFlame = false;

    // Lấy dữ liệu cảm biến sau mỗi chu kỳ (không làm đứng mạch)
    if (currentMillis - prevSensorMillis >= sensorInterval) {
        prevSensorMillis = currentMillis;

        t = dht.readTemperature();
        h = dht.readHumidity();
        isFlame = (digitalRead(FLAME_PIN) == LOW); // Đọc tín hiệu báo lửa

        // Kiểm tra kết nối cảm biến
        if (isnan(h) || isnan(t)) {
            lcd.setCursor(0, 0);
            lcd.print("SENSOR ERROR!!  ");
            return;
        }

        // Dòng 1 LCD: Cập nhật nhiệt độ và độ ẩm liên tục
        lcd.setCursor(0, 0);
        lcd.print("T:" + String((int)t) + "C  H:" + String((int)h) + "%      ");
    }

    // ================= LOGIC ĐIỀU KHIỂN CHỮA CHÁY 3 CẤP ĐỘ =================

    // CẤP ĐỘ 3: HỎA HOẠN (Nhiệt độ cực cao >= 70°C HOẶC phát hiện tia lửa trực tiếp)
    if (t >= 70.0 || isFlame) {
        lcd.setCursor(0, 1);
        lcd.print("!! EVACUATE !!  "); // Yêu cầu sơ tán khẩn cấp

        digitalWrite(RELAY_PUMP, HIGH); // MỞ XẢ VAN NƯỚC/KHÍ CHỮA CHÁY LẬP TỨC
        digitalWrite(FAN_PIN, LOW);     // TẮT QUẠT HÚT (Tránh hút oxy nuôi đám cháy)
        digitalWrite(BUZZER, HIGH);    // Hú còi liên tục không ngừng
    }

    // CẤP ĐỘ 2: CẢNH BÁO NGUY HIỂM (Nhiệt độ phòng tăng cao >= 50°C)
    else if (t >= 50.0) {
        lcd.setCursor(0, 1);
        lcd.print("WARNING: HIGH T ");

        digitalWrite(RELAY_PUMP, LOW);  // Chưa kích hoạt van phun nước
        digitalWrite(FAN_PIN, HIGH);    // Bật quạt tản nhiệt khẩn cấp

        // Còi kêu bíp... bíp... ngắt quãng bằng millis()
        if (currentMillis - prevBuzzerMillis >= buzzerInterval) {
            prevBuzzerMillis = currentMillis;
            buzzerState = !buzzerState;
            digitalWrite(BUZZER, buzzerState);
        }
    }

    // CẤP ĐỘ 1: LÀM MÁT (Nhiệt độ hơi cao >= 35°C hoặc độ ẩm quá khô < 30%)
    else if (t >= 35.0 || h < 30.0) {
        lcd.setCursor(0, 1);
        lcd.print("Status: Cooling ");

        digitalWrite(FAN_PIN, HIGH);    // Bật quạt hút khí nóng/thông gió
        digitalWrite(BUZZER, LOW);      // Tắt còi
        digitalWrite(RELAY_PUMP, LOW);  // Tắt van nước
    }

    // TRẠNG THÁI HỆ THỐNG AN TOÀN BÌNH THƯỜNG
    else {
        lcd.setCursor(0, 1);
        lcd.print("Status: Normal  ");

        digitalWrite(FAN_PIN, LOW);     // Tắt quạt tiết kiệm điện
        digitalWrite(BUZZER, LOW);      // Tắt còi
        digitalWrite(RELAY_PUMP, LOW);  // Tắt van nước
    }
}
